import java.util.*;

class Solution {
  public String largestPalindrome(int n, int k) {
    int half = (n + 1) / 2;
    int[] pow = new int[n];
    pow[0] = 1 % k;
    for (int i = 1; i < n; i++) pow[i] = (pow[i - 1] * 10) % k;
    int[] coeff = new int[half];
    for (int i = 0; i < half; i++) {
      int j = n - 1 - i;
      coeff[i] = (pow[i] + (i == j ? 0 : pow[j])) % k;
    }
    boolean[][] can = new boolean[half + 1][k];
    can[half][0] = true;
    for (int p = half - 1; p >= 0; p--)
      for (int rem = 0; rem < k; rem++)
        for (int d = (p == 0 ? 1 : 0); d <= 9; d++)
          if (can[p + 1][(rem - d * coeff[p] % k + k) % k]) {
            can[p][rem] = true;
            break;
          }
    char[] out = new char[n];
    int need = 0;
    for (int p = 0; p < half; p++) {
      int lo = p == 0 ? 1 : 0;
      for (int d = 9; d >= lo; d--) {
        int next = (need - d * coeff[p] % k + k) % k;
        if (can[p + 1][next]) {
          out[p] = out[n - 1 - p] = (char) ('0' + d);
          need = next;
          break;
        }
      }
    }
    return new String(out);
  }
}
